          Antofagasta: 2,
          Atacama: 3,
          Coquimbo: 4,
          "Valpara\u00EDso": 5,
          "O'Higgins": 6,
          Maule: 7,
          "Biob\u00EDo": 8,
          "Araucan\u00EDa": 9,
          "Los Lagos": 10,
          "Ays\u00E9n": 11,
