    var categorizeOrgs = function (orgs) {
      var cats = {
        Municipalidades: [],
        Salud: [],
        Educación: [],
        "Fuerzas Armadas y Orden": [],
        "Ministerios y Servicios": [],
        Otros: [],
      };
      orgs.forEach(function (o) {
        var n = (o.NombreEmpresa || "").toUpperCase();
        if (
          n.indexOf("MUNICIPALIDAD") > -1 ||
          n.indexOf("ILUSTRE") > -1 ||
          n.indexOf("CORPORACION MUNICIPAL") > -1
        )
          cats["Municipalidades"].push(o);
        else if (
          n.indexOf("HOSPITAL") > -1 ||
          n.indexOf("SALUD") > -1 ||
          n.indexOf("CLINICA") > -1 ||
          n.indexOf("CESFAM") > -1
        )
          cats["Salud"].push(o);
        else if (
          n.indexOf("UNIVERSIDAD") > -1 ||
          n.indexOf("COLEGIO") > -1 ||
          n.indexOf("LICEO") > -1 ||
          n.indexOf("ESCUELA") > -1 ||
          n.indexOf("EDUCACION") > -1 ||
          n.indexOf("JUNJI") > -1
        )
          cats["Educación"].push(o);
        else if (
          n.indexOf("EJERCITO") > -1 ||
          n.indexOf("ARMADA") > -1 ||
          n.indexOf("FACH") > -1 ||
          n.indexOf("CARABINEROS") > -1 ||
          n.indexOf("POLICIA") > -1 ||
          n.indexOf("PDI") > -1 ||
          n.indexOf("GENDARMERIA") > -1
        )
          cats["Fuerzas Armadas y Orden"].push(o);
        else if (
          n.indexOf("MINISTERIO") > -1 ||
          n.indexOf("DIRECCION") > -1 ||
          n.indexOf("SERVICIO") > -1 ||
          n.indexOf("SEREMI") > -1 ||
          n.indexOf("SERVIU") > -1 ||
          n.indexOf("GOBIERNO") > -1 ||
          n.indexOf("SUBSECRETARIA") > -1 ||
          n.indexOf("INTENDENCIA") > -1 ||
          n.indexOf("SUPERINTENDENCIA") > -1 ||
          n.indexOf("FISCALIA") > -1 ||
          n.indexOf("PODER JUDICIAL") > -1
        )
          cats["Ministerios y Servicios"].push(o);
        else cats["Otros"].push(o);
      });
      return cats;
    };
    var orgsFiltrados = (function () {
      if (region === "Todas") return organismosList;
      var regLiteral = region
        .replace(/í/g, "í")
        .replace(/á/g, "á")
        .replace(/é/g, "é")
        .replace(/ó/g, "ó")
        .replace(/ú/g, "ú")
        .replace(/Ñ/g, "Ñ");
      var keywords =
        comunasPorRegion[region] || comunasPorRegion[regLiteral] || [];
      var regLower = region.toLowerCase();
      return organismosList.filter(function (org) {
        var nom = (org.NombreEmpresa || "").toLowerCase();
        if (nom.indexOf(regLower) > -1) return true;
        for (var i = 0; i < keywords.length; i++) {
          if (nom.indexOf(keywords[i]) > -1) return true;
        }
        return false;
      });
    })();

