                          if (idsToUpdate.length === 0)
                            return setToast(
                              "⚠️ Selecciona al menos un precio para adoptar",
                            );

                          const historyRecord = {
                            id: Date.now(),
                            fecha: new Date().toISOString(),
                            proveedor: compareData.proveedor.nombre,
                            count: idsToUpdate.length,
                            items: [],
                          };

                          const newMaterials = materialesArray.map((mat) => {
                            if (idsToUpdate.includes(String(mat.id))) {
                              const change = compareData.items.find(
                                (x) => String(x.id) === String(mat.id),
                              );
                              historyRecord.items.push({
                                matId: mat.id,
                                nombre: mat.nombre,
                                precioAnterior: mat.precio || 0,
                                nuevoPrecio: change.nuevoPrecio,
                              });
                              return {
                                ...mat,
                                precio: change.nuevoPrecio,
                                fechaActualizacion: new Date()
                                  .toISOString()
                                  .split("T")[0],
                              };
                            }
                            return mat;
                          });
